/* Objectif Bac — version refondue. Données locales + IndexedDB pour les médias + Puter.js pour l'IA. */
const SUBJECTS=[
 {id:'hggsp',name:'HGGSP',group:'Spécialité',color:'#8b5cf6'},
 {id:'ses',name:'SES',group:'Spécialité',color:'#f05f8f'},
 {id:'histgeo',name:'Histoire-Géographie',group:'Tronc commun',color:'#3b82f6'},
 {id:'philo',name:'Philosophie',group:'Tronc commun',color:'#f59e0b'},
 {id:'anglais',name:'Anglais',group:'Langue vivante',color:'#0ea5c8'},
 {id:'espagnol',name:'Espagnol',group:'Langue vivante',color:'#ef7d4f'},
 {id:'maths',name:'Mathématiques',group:'Maths',color:'#10a779'},
 {id:'svt',name:'SVT',group:'Tronc commun',color:'#59ad62'},
 {id:'pc',name:'Physique-Chimie',group:'Tronc commun',color:'#7182df'},
 {id:'emc',name:'EMC',group:'Enseignement moral et civique',color:'#858899'},
 {id:'sport',name:'EPS',group:'Sport',color:'#e6b63f'}
];
const WEEKDAYS=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'];
const TABS=[['home','Accueil','⌂'],['courses','Cours','▣'],['revisions','Révisions','✦'],['homework','Devoirs','✓'],['notes','Notes','◌']];
const MORE=[
 ['schedule','Emploi du temps','▤','Cours, contrôles et calendrier'],
 ['bac','Bac 2027','B','Simulation et échéances'],
 ['assistant','Assistant IA','AI','Conversations et photos'],
 ['coaching','Coaching','↗','Objectifs et routine'],
 ['excellence','Excellence','◆','Grand oral et entraînement'],
 ['energy','Énergie','☼','Rythme de travail'],
 ['goals','Objectifs','◎','Objectifs et tâches'],
 ['parcoursup','Parcoursup','P','Liste de formations'],
 ['dates','Échéances','◷','Dates à retenir'],
 ['errors','Erreurs','!','Journal des erreurs'],
 ['shared','Notes partagées','N','Notes synchronisées'],
 ['backup','Sauvegarde','↓','Exporter les données']
];
const KEYS=['weeklyTemplate','weeklyTemplateSeeded','schedule','chapters','courses','homework','todos','errors','grades','energy','subjectSynthesis','homeworkSynthesis','subjectChats','examDates','streak','grandOralQuestions','grandOralAttempts','parcoursupList','weeklyGoals','sharedNotes','bacSimulation'];
const PREFIX='mention:v2:shared:'; const LOCAL_PREFIX='mention:v2:'; const SYNC='/.netlify/functions/sync';
let STATE={weeklyTemplate:[],weeklyTemplateSeeded:false,schedule:[],chapters:{},courses:{},homework:[],todos:[],errors:[],grades:[],energy:[],subjectSynthesis:{},homeworkSynthesis:{},subjectChats:{},examDates:[],streak:{lastVisit:null,count:0},grandOralQuestions:[],grandOralAttempts:[],parcoursupList:[],weeklyGoals:[],sharedNotes:[],bacSimulation:{target:14}};
let active='home',courseSubject='hggsp',courseOpen=null,courseTab={},moreOpen=false,revisionSession=null,revisionMode='dashboard';
let pendingCourseImages=[],pendingCourseTexts=[],hwPending=[];
function storageGet(k){try{return localStorage.getItem(k)}catch{return null}} function storageSet(k,v){try{localStorage.setItem(k,v);return true}catch{return false}}
let aiThreads=[],aiCurrent='',aiPending=[],AI_MODELS=[],AI_SELECTED=storageGet('objectif-bac-ai-model')||'';
let busy=new Set(), aiRendered=false;
const $=id=>document.getElementById(id);
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const today=()=>new Date().toISOString().slice(0,10);
const isoPlus=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const subj=id=>SUBJECTS.find(s=>s.id===id)||SUBJECTS[0];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(d+'T00:00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'short'}):'';
const fmtLong=d=>d?new Date(d+'T00:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}):'';
function read(k){try{const x=localStorage.getItem(PREFIX+k);return x===null?null:JSON.parse(x)}catch{return null}}
function write(k,v){try{localStorage.setItem(PREFIX+k,JSON.stringify(v));localStorage.setItem(LOCAL_PREFIX+k,JSON.stringify(v));return true}catch{return false}}
async function loadState(){for(const k of KEYS){const r=read(k);if(r!==null)STATE[k]=r;else{const x=storageGet(LOCAL_PREFIX+k);if(x)STATE[k]=JSON.parse(x)}}normalize();await migrateImages()}
function normalize(){if(!STATE.chapters)STATE.chapters={};if(!STATE.courses)STATE.courses={};if(!Array.isArray(STATE.homework))STATE.homework=[];if(!Array.isArray(STATE.todos))STATE.todos=[];if(!Array.isArray(STATE.errors))STATE.errors=[];if(!Array.isArray(STATE.grades))STATE.grades=[];if(!STATE.bacSimulation)STATE.bacSimulation={target:14};for(const s of SUBJECTS){if(!Array.isArray(STATE.chapters[s.id]))STATE.chapters[s.id]=[];if(!Array.isArray(STATE.courses[s.id]))STATE.courses[s.id]=[]}}
let saveTimer=null;function save(k){write(k,STATE[k]);clearTimeout(saveTimer);saveTimer=setTimeout(syncState,900)}
async function syncState(){try{await fetch(SYNC,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:'state',value:STATE})})}catch{}}
async function remoteLoad(){try{const r=await fetch(SYNC+'?key=state',{cache:'no-store'});if(r.ok){const j=await r.json();if(j.value&&typeof j.value==='object'){STATE=Object.assign(STATE,j.value);normalize();for(const k of KEYS)write(k,STATE[k])}}}catch{}}
function allCourses(){return Object.values(STATE.courses).flat()}
function chaptersFor(s){return STATE.chapters[s]||[]}
function courseById(id){return allCourses().find(c=>c.id===id)}
function courseSubjectOf(c){return Object.keys(STATE.courses).find(s=>(STATE.courses[s]||[]).some(x=>x.id===c.id))||courseSubject}
function avg(){if(!STATE.grades.length)return null;let p=0,c=0;for(const g of STATE.grades){const n=Number(g.note),co=Number(g.coef||1);if(Number.isFinite(n)){p+=n*co;c+=co}}return c?p/c:null}
function streak(){const s=STATE.streak||{};const t=today();if(s.lastVisit===t)return s.count||1;const prev=isoPlus(-1);s.count=s.lastVisit===prev?(s.count||0)+1:1;s.lastVisit=t;STATE.streak=s;save('streak');return s.count}
/* ---------- IndexedDB ---------- */
const DBNAME='objectif-bac-media-v3';let dbPromise;
function db(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DBNAME,1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('images'))d.createObjectStore('images',{keyPath:'id'});if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return dbPromise}
async function idbPut(store,obj){const d=await db();return new Promise((res,rej)=>{const tx=d.transaction(store,'readwrite');tx.objectStore(store).put(obj);tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error)})}
async function idbGet(store,key){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(store).objectStore(store).get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function idbDelete(store,key){try{const d=await db();d.transaction(store,'readwrite').objectStore(store).delete(key)}catch{}}
async function mediaPut(data,name='Photo'){const id='img_'+uid();await idbPut('images',{id,data,name,createdAt:Date.now()});return id}
async function mediaGet(id){const x=await idbGet('images',id);return x?.data||null}
async function mediaDel(id){return idbDelete('images',id)}
function fileToData(file,max=1400,quality=.78){return new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,max/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',quality))};im.onerror=()=>rej(new Error('Image illisible'));im.src=rd.result};rd.onerror=()=>rej(rd.error);rd.readAsDataURL(file)})}
async function filesToImages(files){const out=[];for(const f of files){if(!f.type.startsWith('image/'))continue;const data=await fileToData(f);const id=await mediaPut(data,f.name);out.push({id,name:f.name,data})}return out}
async function filesToMixed(files){const images=[],texts=[];for(const f of files){if(f.type.startsWith('image/')){const data=await fileToData(f);images.push({id:await mediaPut(data,f.name),name:f.name,data});continue}if(f.type.startsWith('text/')||/\.(txt|md|csv|json)$/i.test(f.name)){texts.push({name:f.name,text:await f.text()});continue}if(/\.(pdf|docx)$/i.test(f.name)||f.type==='application/pdf'||f.type.includes('wordprocessingml')){const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(f)});try{const r=await fetch('/.netlify/functions/extract-document',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.name,type:f.type,data})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Extraction impossible');texts.push({name:f.name,text:String(j.text||'')})}catch(e){texts.push({name:f.name,text:`[Document non extrait : ${e.message}]`})}}}return{images,texts}}
async function migrateImages(){let changed=false;for(const list of Object.values(STATE.courses||{})){for(const c of list){if(Array.isArray(c.images)&&c.images.length){const ids=[];for(const im of c.images){if(im?.id?.startsWith('img_'))ids.push({id:im.id,name:im.name||'Photo'});else if(im?.image_url||im?.data||im?.src){const id=await mediaPut(im.image_url||im.data||im.src,im.name||'Photo');ids.push({id,name:im.name||'Photo'})}}c.imageIds=[...(c.imageIds||[]),...ids];c.imageIds=[...new Map(c.imageIds.map(x=>[typeof x==='string'?x:x.id,typeof x==='string'?{id:x,name:'Photo'}:x])).values()];delete c.images;changed=true}}}if(changed)save('courses')}
async function getImageList(ids=[]){const out=[];for(const x of ids){const id=typeof x==='string'?x:x?.id;if(!id)continue;const data=await mediaGet(id).catch(()=>null);if(data)out.push({id,name:typeof x==='string'?'Photo':x.name||'Photo',data})}return out}
/* ---------- AI ---------- */
function aiText(r){let x=r;if(typeof x==='object'&&x?.message)x=x.message?.content??x.message?.text??x.message;if(Array.isArray(x))x=x.map(v=>typeof v==='string'?v:v?.text||v?.content||'').join('');if(typeof x==='object'&&x)x=x.content??x.text??JSON.stringify(x);return String(x??'')}
function safeJSON(v){if(v&&typeof v==='object')return v;const s=String(v??'').trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();try{return JSON.parse(s)}catch{}const a=s.indexOf('{'),b=s.lastIndexOf('}');if(a>=0&&b>a){try{return JSON.parse(s.slice(a,b+1))}catch{}}return null}
function modelLabel(m){return m?.name||m?.id||'Modèle'}
function visionStatus(m){const c=m?.capabilities||m?.capability||{};if(c.vision===true||c.image===true||c.images===true||m?.vision===true||m?.modalities?.includes?.('image')||m?.input?.includes?.('image'))return true;if(c.vision===false||c.image===false||m?.vision===false)return false;return null} function supportsVision(m){return visionStatus(m)!==false}
function chooseModel(kind='text',hasImages=false){if(AI_SELECTED&&AI_MODELS.some(m=>m.id===AI_SELECTED)&&(!hasImages||visionStatus(AI_MODELS.find(m=>m.id===AI_SELECTED))!==false))return AI_SELECTED;const names=hasImages?['gpt-5.6-luna','gpt-5.5','claude-sonnet-4-6','gemini-3.6-flash','gemini-3.5-flash']:['gpt-5.6-luna','gpt-5.5','gpt-5.4-nano','claude-sonnet-4-6'];const p=AI_MODELS.find(m=>names.includes(m.id));if(p)return p.id;const vision=hasImages&&AI_MODELS.find(supportsVision);return (vision||AI_MODELS[0])?.id||'gpt-5.6-luna'}
async function loadModels(){try{if(!window.puter?.ai?.listModels)return;const m=await puter.ai.listModels();if(Array.isArray(m)&&m.length){AI_MODELS=m.filter(x=>x?.id);if(!AI_SELECTED||!AI_MODELS.some(x=>x.id===AI_SELECTED))AI_SELECTED=chooseModel();storageSet('objectif-bac-ai-model',AI_SELECTED);const c=$('modelCount');if(c)c.textContent=`${AI_MODELS.length} modèles disponibles`}}catch(e){console.warn(e)}}
async function aiCall(prompt,{images=[],model,temperature=.2,max_tokens=9000}={}){if(!window.puter?.ai?.chat)throw new Error('Puter.js n’est pas chargé.');const urls=[];for(const im of images){const data=im.data||await mediaGet(im.id).catch(()=>null);if(data)urls.push(data)}const chosen=model||chooseModel('text',urls.length>0);const base={temperature,max_tokens};const attempts=[chosen,...AI_MODELS.filter(m=>m.id!==chosen&&(!urls.length||visionStatus(m)!==false)) .slice(0,4).map(m=>m.id)];let last;for(const id of attempts){try{const r=await puter.ai.chat(prompt,urls,false,{...base,model:id});return aiText(r)}catch(e){last=e}}throw last||new Error('Appel IA impossible')}
async function aiJSON(prompt,opts={}){const r=await aiCall(prompt,{...opts,temperature:.1});return safeJSON(r)||{raw:aiText(r)}}
function normalizeQuiz(qs){return Array.isArray(qs)?qs.map(q=>{const choices=Array.isArray(q.choices)?q.choices.map(x=>String(x)).slice(0,4):[];let a=Number(q.answer);if(a>=1&&a<=4&&!choices[a])a-=1;return{question:String(q.question||''),choices,answer:Number.isFinite(a)?Math.max(0,Math.min(3,a)):0,explanation:String(q.explanation||'')}}).filter(q=>q.question&&q.choices.length===4):[]} function normalizeFlashcards(fs){return Array.isArray(fs)?fs.map(x=>({front:String(x.front||''),back:String(x.back||'')})).filter(x=>x.front&&x.back):[]}

/* ---------- Gallery ---------- */
let galleryItems=[],galleryIndex=0;
async function openGallery(ids,index=0){galleryItems=await getImageList(ids);galleryIndex=Math.max(0,Math.min(Number(index)||0,galleryItems.length-1));showGallery()}
function showGallery(){if(!galleryItems.length)return;$('galleryImg').src=galleryItems[galleryIndex].data;$('galleryMeta').textContent=`${galleryIndex+1} / ${galleryItems.length}`;$('gallery').classList.add('show')}
function closeGallery(){$('gallery').classList.remove('show')}
function galleryStep(n){if(!galleryItems.length)return;galleryIndex=(galleryIndex+n+galleryItems.length)%galleryItems.length;showGallery()}
$('galleryClose').onclick=closeGallery;$('galleryPrev').onclick=()=>galleryStep(-1);$('galleryNext').onclick=()=>galleryStep(1);$('gallery').onclick=e=>{if(e.target.id==='gallery')closeGallery()};document.addEventListener('keydown',e=>{if(!$('gallery').classList.contains('show'))return;if(e.key==='Escape')closeGallery();if(e.key==='ArrowLeft')galleryStep(-1);if(e.key==='ArrowRight')galleryStep(1)});
/* ---------- Shell ---------- */
function render(){renderTop();renderBottom();renderMore();switch(active){case'home':renderHome();break;case'courses':renderCourses();break;case'revisions':renderRevisions();break;case'homework':renderHomework();break;case'notes':renderNotes();break;case'schedule':renderSchedule();break;case'bac':renderBac();break;case'coaching':renderCoaching();break;case'excellence':renderExcellence();break;case'energy':renderEnergy();break;case'goals':renderGoals();break;case'parcoursup':renderParcoursup();break;case'dates':renderDates();break;case'errors':renderErrors();break;case'shared':renderSharedNotes();break;case'assistant':openAI(true);break}}
function renderTop(){const a=avg();$('app').innerHTML=`<header class="topbar"><button class="brand" id="brandHome"><span class="brandmark">OB</span><span><b>Objectif Bac</b><small>Terminale · Bac 2027</small></span></button><div class="top-actions"><button class="iconbtn" id="searchBtn" aria-label="Rechercher">⌕</button><button class="iconbtn" id="topMore" aria-label="Plus">＋</button></div></header><main id="main"></main>`;$('brandHome').onclick=()=>{active='home';render()};$('searchBtn').onclick=openSearch;$('topMore').onclick=()=>{moreOpen=!moreOpen;renderMore()}}
function renderBottom(){$('bottom').innerHTML=`<nav class="nav">${TABS.map(([id,l,i])=>`<button class="navbtn ${active===id?'active':''}" data-nav="${id}"><span>${i}</span><small>${l}</small></button>`).join('')}<button class="navbtn ${moreOpen?'active':''}" data-nav="more"><span>＋</span><small>Plus</small></button></nav>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='more'){moreOpen=!moreOpen;renderBottom();renderMore();return}active=b.dataset.nav;moreOpen=false;if(active==='assistant')openAI(true);else render()})}
function renderMore(){const s=$('moreSheet'),b=$('sheetBackdrop');if(!s||!b)return;s.innerHTML=`<div class="sheet-grab"></div><div class="sheet-head"><div><b>Tout Objectif Bac</b><small>Accès à tous les outils</small></div><button class="iconbtn" id="closeMore">×</button></div><div class="more-grid">${MORE.map(x=>`<button class="more-btn" data-more="${x[0]}"><span>${x[2]}</span><div><b>${x[1]}</b><small>${x[3]}</small></div></button>`).join('')}</div>`;s.classList.toggle('show',moreOpen);b.classList.toggle('show',moreOpen);$('closeMore').onclick=closeMore;s.querySelectorAll('[data-more]').forEach(x=>x.onclick=()=>{const id=x.dataset.more;closeMore();if(id==='backup')return backupModal();active=id;render()});b.onclick=closeMore}
function closeMore(){moreOpen=false;renderMore();renderBottom()}
function setMain(html){$('main').innerHTML=html}
function openSearch(){const q=prompt('Rechercher dans Objectif Bac');if(!q?.trim())return;const x=globalSearch(q.trim());const rows=[...x.courses.map(v=>({title:v.course.title,meta:`Cours · ${subj(v.subj).name}`,fn:()=>{active='courses';courseSubject=v.subj;courseOpen=v.course.chapterId;render()}})),...x.chapters.map(v=>({title:v.ch.title,meta:`Chapitre · ${subj(v.subj).name}`,fn:()=>{active='courses';courseSubject=v.subj;courseOpen=v.ch.id;render()}})),...x.homework.map(v=>({title:v.title,meta:`Devoir · ${subj(v.subject).name}`,fn:()=>{active='homework';render()}}))];setMain(`<div class="page-title"><div><small>Recherche</small><h2>Résultats pour « ${esc(q)} »</h2></div></div>${rows.length?`<div class="list">${rows.map((r,i)=>`<button class="rowitem" data-sr="${i}"><div class="grow"><b>${esc(r.title)}</b><small>${esc(r.meta)}</small></div><span>›</span></button>`).join('')}</div>`:'<div class="empty"><b>Aucun résultat</b><small>Essaie un autre mot-clé.</small></div>'}`);rows.forEach((r,i)=>$(`[data-sr="${i}"]`).onclick=r.fn)}
function globalSearch(q){const n=q.toLowerCase(),courses=[],chapters=[],homework=[];Object.entries(STATE.courses).forEach(([s,l])=>l.forEach(c=>{if(`${c.title} ${c.structured||''} ${c.summary||''}`.toLowerCase().includes(n))courses.push({subj:s,course:c})}));Object.entries(STATE.chapters).forEach(([s,l])=>l.forEach(c=>{if(String(c.title).toLowerCase().includes(n))chapters.push({subj:s,ch:c})}));STATE.homework.filter(h=>`${h.title} ${h.input||''} ${h.output||''}`.toLowerCase().includes(n)).forEach(h=>homework.push(h));return{courses,chapters,homework}}
/* ---------- Home ---------- */
function renderHome(){const a=avg(),due=revisionDue().length,hw=STATE.homework.filter(x=>!x.done).length,ev=upcomingEvents(5);setMain(`<section class="hero"><div class="hero-copy"><small>TABLEAU DE BORD</small><h1>Objectif Bac 2027</h1><p>Tout ce qu’il faut pour avancer : cours, révisions, devoirs, notes et IA.</p><div class="hero-actions"><button class="btn light" id="homeCourse">Ajouter un cours</button><button class="btn ghost" id="homeRev">Réviser maintenant</button></div></div><div class="hero-score"><small>Moyenne</small><b>${a==null?'—':a.toFixed(2)}</b><span>/20</span></div></section><section class="stats-row"><div class="mini-stat"><span>✦</span><div><small>Série</small><b>${STATE.streak?.count||1} j</b></div></div><div class="mini-stat"><span>R</span><div><small>À revoir</small><b>${due}</b></div></div><div class="mini-stat"><span>✓</span><div><small>Devoirs</small><b>${hw}</b></div></div></section><section class="section"><div class="section-head"><div><small>À venir</small><h2>Prochaines échéances</h2></div><button class="text-btn" id="homeSchedule">Voir le planning</button></div><div class="list">${ev.length?ev.map(e=>`<div class="rowitem"><span class="dot" style="--sc:${subj(e.subject).color}"></span><div class="grow"><b>${esc(e.title)}</b><small>${fmt(e.date)} · ${esc(subj(e.subject).name)}${e.time?' · '+esc(e.time):''}</small></div></div>`).join(''):'<div class="empty"><b>Rien d’urgent</b><small>Ajoute un contrôle ou un devoir dans l’Emploi du temps.</small></div>'}</div></section><section class="section two-col"><div class="panel"><div class="section-head"><div><small>Parcours</small><h2>Mes matières</h2></div></div><div class="subject-list">${SUBJECTS.map(s=>{const n=(STATE.courses[s.id]||[]).length;return `<button class="subject-line" data-home-sub="${s.id}"><span style="--sc:${s.color}">${esc(s.name.slice(0,2))}</span><div class="grow"><b>${esc(s.name)}</b><small>${n} séance${n>1?'s':''}</small></div><span>›</span></button>`}).join('')}</div></div><div class="panel quick"><div class="section-head"><div><small>Accès rapide</small><h2>Continuer</h2></div></div><button class="quick-btn" id="quickAI"><span>AI</span><div><b>Assistant IA</b><small>Question, photo ou explication</small></div>›</button><button class="quick-btn" id="quickRev"><span>✦</span><div><b>Révisions</b><small>${due?due+' question(s) à revoir':'Créer une séance'}</small></div>›</button><button class="quick-btn" id="quickBac"><span>B</span><div><b>Bac 2027</b><small>Simulation et échéances</small></div>›</button></div></section>`);$('homeCourse').onclick=()=>{active='courses';render()};$('homeRev').onclick=()=>startRevision(revisionDue());$('homeSchedule').onclick=()=>{active='schedule';render()};$('quickAI').onclick=()=>openAI(true);$('quickRev').onclick=()=>{active='revisions';render()};$('quickBac').onclick=()=>{active='bac';render()};document.querySelectorAll('[data-home-sub]').forEach(b=>b.onclick=()=>{active='courses';courseSubject=b.dataset.homeSub;render()})}
/* ---------- Courses ---------- */
function subjectChips(){return `<div class="subject-chips">${SUBJECTS.map(s=>`<button class="subject-chip ${courseSubject===s.id?'active':''}" style="--sc:${s.color}" data-csub="${s.id}"><b>${esc(s.name)}</b></button>`).join('')}</div>`}
function renderCourses(){const s=subj(courseSubject),chs=chaptersFor(courseSubject);setMain(`<div class="page-title"><div><small>MES COURS</small><h2>${esc(s.name)}</h2><p>${esc(s.group)} · cours, photos et révision du chapitre.</p></div><button class="btn primary" id="newCourse">＋ Ajouter</button></div>${subjectChips()}<section class="composer panel"><div class="composer-title"><div><b>Nouvelle séance</b><small>Tu peux sélectionner plusieurs photos depuis l’iPhone.</small></div><span class="live-dot">●</span></div><div class="form-grid"><label class="field"><span>Chapitre</span><select id="courseChapter"><option value="">Créer un nouveau chapitre</option>${chs.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label><label class="field"><span>Titre de la séance</span><input id="courseTitle" placeholder="Ex. La puissance américaine"></label><label class="field"><span>Date</span><input id="courseDate" type="date" value="${today()}"></label><label class="field"><span>Heure</span><input id="courseTime" type="time"></label><label class="field full"><span>Notes déjà écrites (facultatif)</span><textarea id="courseRaw" placeholder="Tu peux laisser vide si les photos contiennent tout."></textarea></label></div><div class="upload-row"><label class="upload"><span>＋</span><div><b>Ajouter des photos</b><small>7, 10, 20 photos…</small></div><input id="courseFiles" type="file" accept="image/*,.pdf,.docx,.txt,.md,.csv,.json" multiple hidden></label><button class="btn primary" id="generateCourse">Enregistrer & générer</button></div><div id="coursePreview"></div><div id="courseStatus"></div></section><section class="section"><div class="section-head"><div><small>ORGANISATION</small><h2>Chapitres</h2></div><span>${chs.length} chapitre${chs.length>1?'s':''}</span></div><div class="chapter-list">${chs.length?chs.slice().reverse().map(ch=>renderChapter(ch,s)).join(''):'<div class="empty"><b>Aucun chapitre</b><small>Ajoute une première séance pour créer ton parcours.</small></div>'}</div></section>`);document.querySelectorAll('[data-csub]').forEach(b=>b.onclick=()=>{courseSubject=b.dataset.csub;courseOpen=null;render()});$('newCourse').onclick=()=>$('courseTitle').focus();$('courseFiles').onchange=async e=>{try{const mixed=await filesToMixed([...e.target.files]);pendingCourseImages.push(...mixed.images);pendingCourseTexts.push(...mixed.texts);renderCoursePreview()}catch(err){$('coursePreview').innerHTML='<div class="notice error">Impossible de lire une photo : '+esc(err.message||err)+'</div>'}};$('generateCourse').onclick=generateCourse}
function renderCoursePreview(){const p=$('coursePreview');if(!p)return;p.innerHTML=pendingCourseImages.length?`<div class="preview-head"><b>${pendingCourseImages.length} photo(s) sélectionnée(s)</b><button class="text-btn" id="clearCoursePhotos">Tout retirer</button></div><div class="thumbs">${pendingCourseImages.map((x,i)=>`<button class="thumb" data-pimg="${i}"><img src="${x.data}"><span>${i+1}</span></button>`).join('')}</div><small class="muted">Les photos sont déjà sauvegardées avant le lancement de l’IA.</small>`:'<small class="muted">Aucune photo sélectionnée.</small>';document.querySelectorAll('[data-pimg]').forEach(b=>b.onclick=()=>openGallery(pendingCourseImages.map(x=>x.id),Number(b.dataset.pimg)));$('clearCoursePhotos')?.addEventListener('click',()=>{pendingCourseImages=[];pendingCourseTexts=[];renderCoursePreview()})}
function stageInit(){return{photos:true,transcription:false,course:false,study:false,resources:false}}
async function generateCourse(){if(busy.has('course'))return;const btn=$('generateCourse'),title=($('courseTitle').value||'').trim(),raw=($('courseRaw').value||'').trim(),selected=$('courseChapter').value;if(!title&&!selected&&!raw&&!pendingCourseImages.length&&!pendingCourseTexts.length){$('courseStatus').innerHTML='<div class="notice error">Ajoute un titre, du texte ou au moins une photo.</div>';return}busy.add('course');btn.disabled=true;let ch=selected?chaptersFor(courseSubject).find(x=>x.id===selected):null;if(!ch){ch={id:uid(),title:title||'Nouveau chapitre',date:today()};STATE.chapters[courseSubject].push(ch);save('chapters')}const c={id:uid(),chapterId:ch.id,title:title||ch.title,date:$('courseDate').value||today(),time:$('courseTime').value||'',raw:[raw,...pendingCourseTexts.map(x=>`--- ${x.name} ---\n${x.text}`)].filter(Boolean).join('\n\n'),transcription:'',structured:'',summary:'',keyTerms:[],flashcards:[],cards:[],resources:'',youtubeQuery:title||ch.title,youtubeTitle:'',youtubeUrl:'',imageIds:pendingCourseImages.map(x=>({id:x.id,name:x.name})),status:'saved',stages:stageInit(),progressStage:'photos',progressText:'Photos enregistrées. Préparation…'};STATE.courses[courseSubject].push(c);save('courses');pendingCourseImages=[];pendingCourseTexts=[];courseOpen=ch.id;renderCourses();await continueCoursePipeline(c.id);busy.delete('course')}
async function continueCoursePipeline(id){const c=courseById(id);if(!c)return;const setStage=(stage,text)=>{c.progressStage=stage;c.progressText=text;c.status='processing';save('courses');if(active==='courses')renderCourses()};try{const imgs=await getImageList(c.imageIds||[]);if(!c.stages.transcription){setStage('transcription','Étape 1/5 · transcription fidèle des photos…');c.transcription=imgs.length?await aiCall(`Tu retranscris des notes de cours de Terminale. Retranscris TOUT ce qui est lisible dans les photos, dans l’ordre exact des photos. Ne résume pas. Respecte titres, définitions, exemples, chiffres et tableaux quand ils sont lisibles. Quand un passage est impossible à lire, écris [illisible]. Cours : ${c.title}`,{images:imgs,max_tokens:14000}):c.raw;c.stages.transcription=true;save('courses')}if(!c.stages.course){setStage('course','Étape 2/5 · création du cours complet…');const source=String(c.transcription||c.raw||'').slice(0,120000);const p=await aiJSON(`Transforme cette transcription en un vrai cours complet de Terminale, long, structuré et pédagogique. Ne fais pas seulement un résumé. JSON strict avec : structured (cours complet avec titres et explications), summary (résumé clair), keyTerms (tableau [{term,definition}]), plan (tableau de titres). N'invente pas des informations absentes de la source. Source :\n${source}`,{max_tokens:15000});c.structured=String(p.structured||p.raw||source);c.summary=String(p.summary||'');c.keyTerms=Array.isArray(p.keyTerms)?p.keyTerms:[];c.stages.course=true;save('courses')}if(!c.stages.study){setStage('study','Étape 3/5 · fiches et QCM interactifs…');const p=await aiJSON(`À partir de ce cours, crée un vrai entraînement. JSON strict : flashcards=[{front,back}] avec 12 cartes progressives ; quiz=[{question,choices,answer,explanation}] avec 10 QCM, choices doit contenir 4 réponses et answer doit être l'index 0 à 3. Les questions doivent tester le cours, sans inventer. Cours :\n${c.structured}`,{max_tokens:12000});c.flashcards=normalizeFlashcards(p.flashcards);c.cards=normalizeQuiz(p.quiz);c.stages.study=true;save('courses')}if(!c.stages.resources){setStage('resources','Étape 4/5 · recherche de ressources ciblées…');const p=await aiJSON(`Pour le chapitre scolaire « ${c.title} », donne une ressource vidéo YouTube réellement exploitable si tu connais une URL fiable, sinon donne youtubeQuery précis. Donne aussi 3 ressources web sous forme de liens seulement si tu es certain de leur URL. JSON strict : youtubeUrl, youtubeTitle, youtubeQuery, resources (tableau de {title,url,description}). Ne fabrique jamais une URL.`,{max_tokens:3500});c.youtubeUrl=validYoutube(p.youtubeUrl)?p.youtubeUrl:'';c.youtubeTitle=String(p.youtubeTitle||'Vidéo ciblée');c.youtubeQuery=String(p.youtubeQuery||c.title);c.resources=Array.isArray(p.resources)?p.resources.filter(x=>x&&x.url):[];c.stages.resources=true;save('courses')}c.status='ready';c.progressStage='';c.progressText='Package terminé : transcription, cours complet, résumé, notions, fiches, QCM et ressources.';save('courses');if(active==='courses')renderCourses()}catch(e){c.status='partial';c.progressStage='';c.progressText='Une étape a échoué, mais tout ce qui a déjà été généré est conservé.';c.lastError=String(e?.message||e);save('courses');if(active==='courses')renderCourses()}}
function validYoutube(u){try{const x=new URL(String(u||''));return /(^|\.)youtube\.com$|(^|\.)youtu\.be$/.test(x.hostname)}catch{return false}}
function renderChapter(ch,s){const sessions=(STATE.courses[s.id]||[]).filter(c=>c.chapterId===ch.id),open=courseOpen===ch.id;return `<article class="chapter-card" style="--sc:${s.color}"><div class="chapter-head"><button class="chapter-toggle" data-open-ch="${ch.id}"><span class="subject-avatar">${esc(s.name.slice(0,2))}</span><span class="grow"><b>${esc(ch.title)}</b><small>${sessions.length} séance${sessions.length>1?'s':''} · ${sessions.reduce((n,c)=>n+(c.imageIds?.length||0),0)} photo(s)</small></span><span class="chev">${open?'⌃':'›'}</span></button><div class="chapter-tools"><button class="iconbtn small" data-edit-ch="${ch.id}" title="Renommer">✎</button><button class="iconbtn small danger" data-del-ch="${ch.id}" title="Supprimer">×</button></div></div>${open?`<div class="chapter-body">${sessions.length?sessions.slice().reverse().map(renderCourseSession).join(''):'<div class="empty">Aucune séance.</div>'}</div>`:''}</article>`}
function renderCourseSession(c){const imgs=c.imageIds||[],tab=courseTab[c.id]||'course',tabs=[['course','Cours'],['transcription','Transcription'],['summary','Résumé'],['terms','Notions'],['cards','Fiches'],['quiz','QCM'],['resources','Ressources']];return `<article class="session-card" data-session="${c.id}"><div class="session-head"><div><small>${fmt(c.date)}${c.time?' · '+c.time:''}</small><h3>${esc(c.title)}</h3></div><div class="session-actions"><span class="status ${c.status}">${c.status==='ready'?'Prêt':c.status==='partial'?'Partiel':'En cours'}</span><button class="iconbtn small" data-regenc="${c.id}" title="Relancer">↻</button><button class="iconbtn small danger" data-delc="${c.id}" title="Supprimer">×</button></div></div>${imgs.length?`<div class="thumbs">${imgs.map((x,i)=>`<button class="thumb" data-img-session="${c.id}" data-img-index="${i}"><img data-lazy-img="${esc(x.id)}"><span>${i+1}</span></button>`).join('')}</div>`:''}<div class="pipeline">${['photos','transcription','course','study','resources'].map(k=>`<span class="${c.stages?.[k]?'done':''} ${c.progressStage===k?'work':''}"></span>`).join('')}</div>${c.progressText?`<div class="notice ${c.status==='partial'?'error':c.status==='ready'?'ok':''}">${esc(c.progressText)}${c.status==='partial'?`<small class="error-text">${esc(c.lastError||'')}</small><div class="actions"><button class="btn small" data-retry="${c.id}">Reprendre</button></div>`:''}</div>`:''}<div class="tabs2">${tabs.map(([id,l])=>`<button class="tab2 ${tab===id?'active':''}" data-ctab="${id}" data-cid="${c.id}">${l}</button>`).join('')}</div><div class="session-content">${courseTabContent(c,tab)}</div></article>`}
function courseTabContent(c,t){if(t==='course')return `<div class="richtext">${esc(c.structured||'Le cours complet sera disponible après la génération.')}</div>`;if(t==='transcription')return `<div class="richtext">${esc(c.transcription||c.raw||'Aucune transcription.')}</div>`;if(t==='summary')return `<div class="richtext">${esc(c.summary||'Aucun résumé généré.')}</div>`;if(t==='terms')return c.keyTerms?.length?`<div class="terms">${c.keyTerms.map(x=>`<div class="term"><b>${esc(x.term)}</b><span>${esc(x.definition)}</span></div>`).join('')}</div>`:'<div class="empty">Les notions apparaîtront ici après génération.</div>';if(t==='cards')return c.flashcards?.length?`<div class="study-grid">${c.flashcards.map((x,i)=>`<button class="flashcard" data-flip="${c.id}:${i}"><span class="front"><b>${esc(x.front)}</b><small>Toucher pour retourner</small></span><span class="back"><b>Réponse</b><span>${esc(x.back)}</span><small>Toucher pour revenir</small></span></button>`).join('')}</div>`:'<div class="empty">Les fiches apparaîtront ici après génération.</div>';if(t==='quiz')return c.cards?.length?`<div class="quiz-list">${c.cards.map((q,i)=>`<div class="qcm" data-qcm="${c.id}:${i}"><small>Question ${i+1}/${c.cards.length}</small><h4>${esc(q.question)}</h4><div class="answers">${(q.choices||[]).map((a,j)=>`<button class="answer" data-answer="${j}">${esc(a)}</button>`).join('')}</div><div class="feedback" data-feedback></div></div>`).join('')}</div>`:'<div class="empty">Aucun QCM généré.</div>';return `<div class="resources"><div class="resource-video"><div><small>VIDÉO</small><b>${esc(c.youtubeTitle||'Vidéo ciblée')}</b><span>${esc(c.youtubeQuery||c.title)}</span></div>${c.youtubeUrl?`<a class="btn soft" href="${esc(c.youtubeUrl)}" target="_blank" rel="noopener">Voir la vidéo</a>`:`<a class="btn soft" href="https://www.youtube.com/results?search_query=${encodeURIComponent(c.youtubeQuery||c.title)}" target="_blank" rel="noopener">Chercher sur YouTube</a>`}</div>${Array.isArray(c.resources)&&c.resources.length?c.resources.map(r=>`<a class="resource" href="${esc(r.url)}" target="_blank" rel="noopener"><b>${esc(r.title||r.url)}</b><small>${esc(r.description||'')}</small></a>`).join(''):'<div class="empty">Pas de ressource web vérifiée pour le moment.</div>'}</div>`}
/* ---------- Revisions ---------- */
function reviewStore(){try{return JSON.parse(storageGet('objectif-bac-review-v3')||'{}')}catch{return {}}}
function saveReview(r){storageSet('objectif-bac-review-v3',JSON.stringify(r))}
function cardKey(c,i,type='quiz'){return `${c.id}_${type}_${i}`}
function revisionDue(){const r=reviewStore(),out=[];for(const c of allCourses()){(c.cards||[]).forEach((q,i)=>{const x=r[cardKey(c,i,'quiz')];if(!x||!x.due||x.due<=Date.now())out.push({c,q,i,x,kind:'quiz'})});(c.flashcards||[]).forEach((q,i)=>{const x=r[cardKey(c,i,'flash')];if(!x||!x.due||x.due<=Date.now())out.push({c,q,i,x,kind:'flash'})})}return out}
function updateReview(c,i,quality,type='quiz'){const r=reviewStore(),k=cardKey(c,i,type),x=r[k]||{reps:0,ease:2.5,interval:0};if(quality===0){x.reps=0;x.interval=0;x.ease=Math.max(1.3,x.ease-.2)}else{x.reps++;x.ease=Math.max(1.3,x.ease+(quality===3?.15:quality===2?.05:-.15));x.interval=x.reps===1?1:x.reps===2?3:Math.max(1,Math.round(x.interval*x.ease))}x.last=Date.now();x.due=Date.now()+x.interval*86400000;r[k]=x;saveReview(r)}
function startRevision(pool=revisionDue()){if(!pool.length){revisionMode='dashboard';render();return}revisionSession={queue:pool.slice(0,15),index:0,revealed:false,answered:false,score:0};revisionMode='session';render()}
function renderRevisions(){if(revisionMode==='session'&&revisionSession)return renderRevisionSession();const due=revisionDue(),cards=allCourses().filter(c=>c.cards?.length),qCount=cards.reduce((n,c)=>n+c.cards.length,0),subjects=SUBJECTS.map(s=>({s,n:cards.filter(c=>courseSubjectOf(c)===s.id).reduce((n,c)=>n+c.cards.length,0)})).filter(x=>x.n);const chapters=Object.entries(STATE.chapters).flatMap(([sid,chs])=>chs.map(ch=>{const cs=(STATE.courses[sid]||[]).filter(c=>c.chapterId===ch.id),n=cs.reduce((a,c)=>a+(c.cards?.length||0),0);return n?`<button class="revision-chapter" data-revchap="${sid}:${ch.id}"><span style="--sc:${subj(sid).color}">${esc(subj(sid).name.slice(0,2))}</span><div class="grow"><b>${esc(ch.title)}</b><small>${subj(sid).name} · ${n} questions</small></div><strong>›</strong></button>`:''}).filter(Boolean).join(''));setMain(`<div class="page-title"><div><small>APPRENDRE</small><h2>Révisions</h2><p>Des séances courtes, des fiches interactives et de la répétition espacée.</p></div><button class="btn primary" id="revStart">Commencer</button></div><section class="revision-hero"><div><small>À revoir aujourd’hui</small><b>${due.length}</b><span>${due.length?'question(s) prêtes pour une séance':'Aucune urgence'}</span></div><button class="btn light" id="revDue">Révision du jour</button></section><section class="stats-row"><div class="mini-stat"><span>R</span><div><small>À revoir</small><b>${due.length}</b></div></div><div class="mini-stat"><span>▣</span><div><small>Chapitres</small><b>${Object.values(STATE.chapters).flat().length}</b></div></div><div class="mini-stat"><span>?</span><div><small>QCM</small><b>${qCount}</b></div></div></section><section class="section two-col"><div class="panel"><div class="section-head"><div><small>SÉANCE</small><h2>Choisir un mode</h2></div></div><button class="mode-card" id="revFlash"><span>▤</span><div><b>Fiches mémoire</b><small>Retourne les cartes puis indique ton niveau.</small></div>›</button><button class="mode-card" id="revQuiz"><span>?</span><div><b>QCM express</b><small>10 questions mélangées avec correction.</small></div>›</button></div><div class="panel"><div class="section-head"><div><small>MATIÈRES</small><h2>Mon parcours</h2></div></div>${subjects.length?subjects.map(x=>`<button class="subject-line" data-revsub="${x.s.id}"><span style="--sc:${x.s.color}">${esc(x.s.name.slice(0,2))}</span><div class="grow"><b>${esc(x.s.name)}</b><small>${x.n} questions</small></div>›</button>`).join(''):'<div class="empty"><b>Aucun contenu</b><small>Crée un cours puis génère ses fiches et QCM.</small></div>'}</div></section><section class="section"><div class="section-head"><div><small>PARCOURS</small><h2>Chapitres à travailler</h2></div></div><div class="revision-list">${chapters||'<div class="empty">Aucun chapitre avec entraînement.</div>'}</div></section>`);$('revStart').onclick=()=>startRevision(due.length?due:cards.flatMap(c=>c.cards.map((q,i)=>({c,q,i}))).slice(0,15));$('revDue').onclick=()=>startRevision(due);$('revFlash').onclick=()=>startRevision(cards.flatMap(c=>c.flashcards.map((f,i)=>({c,q:{front:f.front,back:f.back},i}))));$('revQuiz').onclick=()=>startRevision(cards.flatMap(c=>c.cards.map((q,i)=>({c,q,i}))).sort(()=>Math.random()-.5).slice(0,10));document.querySelectorAll('[data-revsub]').forEach(b=>b.onclick=()=>{const pool=cards.filter(c=>courseSubjectOf(c)===b.dataset.revsub).flatMap(c=>c.cards.map((q,i)=>({c,q,i})));startRevision(pool)});document.querySelectorAll('[data-revchap]').forEach(b=>b.onclick=()=>{const [s,ch]=b.dataset.revchap.split(':');const pool=(STATE.courses[s]||[]).filter(c=>c.chapterId===ch).flatMap(c=>c.cards.map((q,i)=>({c,q,i})));startRevision(pool)})}
function renderRevisionSession(){const x=revisionSession,q=x.queue[x.index],total=x.queue.length;if(!q){revisionMode='dashboard';revisionSession=null;render();return}const isFlash=!q.q.choices,progress=Math.round(x.index/total*100);setMain(`<div class="page-title"><div><small>SESSION ${x.index+1}/${total}</small><h2>${isFlash?'Fiche mémoire':'QCM'}</h2><p>${esc(q.c.title)}</p></div><button class="btn" id="quitRev">Quitter</button></div><div class="session-progress"><span style="width:${progress}%"></span></div><section class="revision-card"><small>${esc(subj(courseSubjectOf(q.c)).name)}</small><h2>${esc(isFlash?q.q.front:q.q.question)}</h2>${isFlash?`<button class="big-flip ${x.revealed?'revealed':''}" id="revFlip"><span class="front">Toucher pour révéler la réponse</span><span class="back">${esc(q.q.back||'')}</span></button>${x.revealed?`<div class="rating"><button data-rate="0">À revoir</button><button data-rate="2">Bien</button><button data-rate="3">Facile</button></div>`:''}`:`<div class="answers big">${(q.q.choices||[]).map((a,i)=>`<button class="answer" data-revans="${i}">${esc(a)}</button>`).join('')}</div>${x.answered?`<div class="notice ${x.correct?'ok':'error'}">${x.correct?'Bonne réponse.':'Pas tout à fait.'} ${esc(q.q.explanation||'')}<div class="actions"><button class="btn primary" id="nextRev">${x.index===total-1?'Terminer':'Continuer'}</button></div></div>`:''}`}</section>`);$('quitRev').onclick=()=>{revisionSession=null;revisionMode='dashboard';render()};$('revFlip')?.addEventListener('click',()=>{revisionSession.revealed=true;renderRevisionSession()});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{updateReview(q.c,q.i,Number(b.dataset.rate),isFlash?'flash':'quiz');x.index++;x.revealed=false;renderRevisionSession()});document.querySelectorAll('[data-revans]').forEach(b=>b.onclick=()=>{if(x.answered)return;x.answered=true;x.correct=Number(b.dataset.revans)===Number(q.q.answer);if(x.correct)x.score++;updateReview(q.c,q.i,x.correct?2:0,'quiz');renderRevisionSession()});$('nextRev')?.addEventListener('click',()=>{x.index++;x.answered=false;x.revealed=false;renderRevisionSession()})}
/* ---------- Homework ---------- */
function renderHomework(){const list=STATE.homework.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));setMain(`<div class="page-title"><div><small>À FAIRE</small><h2>Devoirs</h2><p>Garde tes devoirs, leurs photos et l’aide IA au même endroit.</p></div><button class="btn primary" id="hwTop">＋ Nouveau</button></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Matière</span><select id="hwSubj">${SUBJECTS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label class="field"><span>Date</span><input id="hwDate" type="date" value="${today()}"></label><label class="field full"><span>Intitulé</span><input id="hwTitle" placeholder="Ex. DM chapitre 4"></label><label class="field full"><span>Consigne / énoncé</span><textarea id="hwInput" placeholder="Écris la consigne ou ajoute des photos."></textarea></label></div><div class="upload-row"><label class="upload"><span>＋</span><div><b>Ajouter des photos</b><small>Plusieurs photos acceptées</small></div><input id="hwFiles" type="file" accept="image/*,.pdf,.docx,.txt,.md" multiple hidden></label><button class="btn primary" id="hwSave">Enregistrer</button><button class="btn" id="hwSaveAI">Enregistrer + IA</button></div><div id="hwPreview"></div><div id="hwStatus"></div></section><section class="section"><div class="section-head"><div><small>HISTORIQUE</small><h2>Mes devoirs</h2></div><span>${list.length}</span></div><div class="homework-list">${list.length?list.map(renderHomeworkCard).join(''):'<div class="empty"><b>Aucun devoir</b><small>Ajoute ton premier devoir.</small></div>'}</div></section>`);$('hwTop').onclick=()=>document.getElementById('hwTitle').focus();$('hwFiles').onchange=async e=>{try{const mixed=await filesToMixed([...e.target.files]);hwPending.push(...mixed.images);if(mixed.texts.length)$('hwInput').value=[$('hwInput').value,...mixed.texts.map(x=>`--- ${x.name} ---\n${x.text}`)].filter(Boolean).join('\n');renderHWPreview()}catch(err){$('hwStatus').innerHTML='<div class="notice error">Impossible de lire une photo : '+esc(err.message||err)+'</div>'}};$('hwSave').onclick=()=>saveHomework(false);$('hwSaveAI').onclick=()=>saveHomework(true);document.querySelectorAll('[data-hw-del]').forEach(b=>b.onclick=()=>deleteHomework(b.dataset.hwDel));document.querySelectorAll('[data-hw-done]').forEach(b=>b.onclick=()=>toggleHomework(b.dataset.hwDone));document.querySelectorAll('[data-hw-ai]').forEach(b=>b.onclick=()=>runHomeworkAI(b.dataset.hwAi));loadLazyImages()}
function renderHWPreview(){const p=$('hwPreview');if(!p)return;p.innerHTML=hwPending.length?`<div class="preview-head"><b>${hwPending.length} photo(s)</b></div><div class="thumbs">${hwPending.map((x,i)=>`<button class="thumb" data-hwp="${i}"><img src="${x.data}"></button>`).join('')}</div>`:'';document.querySelectorAll('[data-hwp]').forEach(b=>b.onclick=()=>openGallery(hwPending.map(x=>x.id),Number(b.dataset.hwp)))}
function renderHomeworkCard(h){return `<article class="homework-card ${h.done?'done':''}"><div class="session-head"><div><small>${fmt(h.date)} · ${esc(subj(h.subject).name)}</small><h3>${esc(h.title)}</h3></div><span class="status">${h.done?'Terminé':'À faire'}</span></div>${h.imageIds?.length?`<div class="thumbs">${h.imageIds.map((x,i)=>`<button class="thumb" data-hwimg="${h.id}" data-hi="${i}"><img data-lazy-img="${esc(x.id)}"><span>${i+1}</span></button>`).join('')}</div>`:''}${h.input?`<details><summary>Voir l’énoncé</summary><div class="richtext">${esc(h.input)}</div></details>`:''}${h.output?`<div class="ai-output"><small>AIDE IA</small><div class="richtext">${esc(h.output)}</div></div>`:''}<div class="actions"><button class="btn small" data-hw-done="${h.id}">${h.done?'Marquer à faire':'Marquer terminé'}</button><button class="btn small" data-hw-ai="${h.id}">IA aide / correction</button><button class="btn small danger" data-hw-del="${h.id}">Supprimer</button></div></article>`}
async function saveHomework(withAI){const title=($('hwTitle').value||'').trim()||'Devoir sans titre',h={id:uid(),subject:$('hwSubj').value,date:$('hwDate').value||today(),title,input:$('hwInput').value||'',imageIds:hwPending.map(x=>({id:x.id,name:x.name})),done:false,output:''};STATE.homework.push(h);save('homework');hwPending=[];render();if(withAI)await runHomeworkAI(h.id)}
async function runHomeworkAI(id){const h=STATE.homework.find(x=>x.id===id);if(!h||busy.has('hwai_'+id))return;busy.add('hwai_'+id);h.output='Analyse IA en cours…';save('homework');if(active==='homework')render();try{h.output=await aiCall(`Tu aides une élève de Terminale avec ce devoir. Donne une aide pédagogique : méthode, raisonnement, correction si possible, et signale clairement ce qui est incertain. Ne fais pas semblant d'avoir vu une information absente. Matière : ${subj(h.subject).name}\nTitre : ${h.title}\nÉnoncé :\n${h.input}`,{images:await getImageList(h.imageIds||[]),max_tokens:7000});save('homework')}catch(e){h.output='Erreur IA : '+String(e.message||e);save('homework')}finally{busy.delete('hwai_'+id);if(active==='homework')render()}}
function deleteHomework(id){const h=STATE.homework.find(x=>x.id===id);if(!h)return;for(const x of h.imageIds||[])mediaDel(typeof x==='string'?x:x.id);STATE.homework=STATE.homework.filter(x=>x.id!==id);save('homework');render()}
function toggleHomework(id){const h=STATE.homework.find(x=>x.id===id);if(h){h.done=!h.done;save('homework');render()}}
/* ---------- Notes ---------- */
function renderNotes(){const a=avg(),rows=STATE.grades.slice().reverse();setMain(`<div class="page-title"><div><small>SUIVI</small><h2>Notes</h2><p>Une vue simple de tes résultats par matière.</p></div></div><div class="stats-row"><div class="mini-stat"><span>★</span><div><small>Moyenne</small><b>${a==null?'—':a.toFixed(2)}/20</b></div></div><div class="mini-stat"><span>▤</span><div><small>Évaluations</small><b>${rows.length}</b></div></div><div class="mini-stat"><span>•</span><div><small>Matières</small><b>${new Set(rows.map(x=>x.subject)).size}</b></div></div></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Matière</span><select id="gradeSubj">${SUBJECTS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label class="field"><span>Note /20</span><input id="gradeNote" type="number" min="0" max="20" step="0.25"></label><label class="field"><span>Coefficient</span><input id="gradeCoef" type="number" min="0.5" step="0.5" value="1"></label><label class="field"><span>Évaluation</span><input id="gradeTitle" placeholder="Contrôle, DM…"></label></div><div class="actions"><button class="btn primary" id="addGrade">Ajouter la note</button><button class="btn" id="gradeAI">Analyser avec l’IA</button></div></section><section class="section panel"><div class="section-head"><div><small>HISTORIQUE</small><h2>Mes notes</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Matière</th><th>Évaluation</th><th>Note</th><th>Coef.</th><th></th></tr></thead><tbody>${rows.map(g=>`<tr><td>${esc(subj(g.subject).name)}</td><td>${esc(g.title||'Note')}</td><td><b>${Number(g.note).toFixed(2)}</b></td><td>${esc(g.coef||1)}</td><td><button class="iconbtn small danger" data-grade-del="${g.id}">×</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Aucune note pour le moment.</div>':''}</div></section>`);$('gradeAI').onclick=async()=>{const out=document.createElement('div');out.className='ai-output';out.innerHTML='<span class="loading"><i class="spin"></i> Analyse…</span>';document.querySelector('.composer').appendChild(out);try{out.innerHTML='<div class="richtext">'+esc(await aiCall('Analyse ce relevé de notes et donne des pistes de travail concrètes sans jugement. Notes : '+STATE.grades.map(g=>subj(g.subject).name+' '+g.note+'/20 coef '+g.coef).join(', ')))+'</div>'}catch(e){out.innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}};$('addGrade').onclick=()=>{const n=Number($('gradeNote').value),co=Number($('gradeCoef').value||1);if(!Number.isFinite(n)||n<0||n>20)return alert('Note invalide');STATE.grades.push({id:uid(),subject:$('gradeSubj').value,note:n,coef:co,title:$('gradeTitle').value||'Évaluation',date:today()});save('grades');render()};document.querySelectorAll('[data-grade-del]').forEach(b=>b.onclick=()=>{STATE.grades=STATE.grades.filter(x=>x.id!==b.dataset.gradeDel);save('grades');render()})}
/* ---------- Schedule ---------- */
function templateForDate(iso){const day=WEEKDAYS[(new Date(iso+'T00:00:00').getDay()+6)%7];return(STATE.weeklyTemplate||[]).filter(e=>e.day===day).map(e=>({...e,id:`tpl_${e.id}_${iso}`,date:iso,template:true}))}
function eventsForDate(iso){return[...(STATE.schedule||[]).filter(e=>e.date===iso),...templateForDate(iso)].sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function upcomingEvents(days){const out=[];for(let i=0;i<days;i++)out.push(...eventsForDate(isoPlus(i)));return out.sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||''))).slice(0,8)}
function weekStart(){const d=new Date(),n=(d.getDay()+6)%7;d.setDate(d.getDate()-n);d.setHours(0,0,0,0);return d}
function renderSchedule(){const start=weekStart(),days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});setMain(`<div class="page-title"><div><small>ORGANISATION</small><h2>Emploi du temps</h2><p>Semaine, contrôles, DM et créneaux récurrents.</p></div></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Intitulé</span><input id="evTitle" placeholder="Cours, contrôle, DM…"></label><label class="field"><span>Date</span><input id="evDate" type="date" value="${today()}"></label><label class="field"><span>Heure</span><input id="evTime" type="time"></label><label class="field"><span>Matière</span><select id="evSubj">${SUBJECTS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label class="field"><span>Répétition</span><select id="evRepeat"><option value="once">Une fois</option><option value="weekly">Chaque semaine</option></select></label><label class="field" id="evDayWrap" style="display:none"><span>Jour</span><select id="evDay">${WEEKDAYS.map(d=>`<option value="${d}">${d[0].toUpperCase()+d.slice(1)}</option>`).join('')}</select></label></div><div class="actions"><button class="btn primary" id="saveEvent">Ajouter</button></div></section><section class="section week-grid">${days.map(d=>{const iso=d.toISOString().slice(0,10),ev=eventsForDate(iso);return `<div class="day-card ${iso===today()?'today':''}"><div class="day-title"><b>${d.toLocaleDateString('fr-FR',{weekday:'short'})}</b><strong>${d.getDate()}</strong></div><div class="day-events">${ev.length?ev.map(e=>`<div class="day-event" style="--sc:${subj(e.subject).color}"><span>${e.time||'—'}</span><b>${esc(e.title)}</b>${e.template?'':'<button data-ev-del="'+e.id+'">×</button>'}</div>`).join(''):'<small>Aucun événement</small>'}</div></div>`}).join('')}</section><section class="section panel"><div class="section-head"><div><small>RÉCURRENTS</small><h2>Créneaux fixes</h2></div><span>${(STATE.weeklyTemplate||[]).length}</span></div><div class="list">${(STATE.weeklyTemplate||[]).map(e=>`<div class="rowitem"><span class="dot" style="--sc:${subj(e.subject).color}"></span><div class="grow"><b>${esc(e.title)}</b><small>${esc(e.day)} · ${e.time||'—'} · ${esc(subj(e.subject).name)}</small></div><button class="iconbtn small danger" data-tpl-del="${e.id}">×</button></div>`).join('')||'<div class="empty">Aucun créneau récurrent.</div>'}</div></section><section class="section panel"><div class="section-head"><div><small>CALENDRIER</small><h2>Mois en cours</h2></div></div>${renderCalendar()}</section>`);$('evRepeat').onchange=e=>$('evDayWrap').style.display=e.target.value==='weekly'?'':'none';$('saveEvent').onclick=()=>{const title=$('evTitle').value.trim();if(!title)return alert('Ajoute un intitulé');if($('evRepeat').value==='weekly'){STATE.weeklyTemplate.push({id:uid(),day:$('evDay').value,time:$('evTime').value||'',subject:$('evSubj').value,title});save('weeklyTemplate')}else{STATE.schedule.push({id:uid(),date:$('evDate').value||today(),time:$('evTime').value||'',subject:$('evSubj').value,title});save('schedule')}render()};document.querySelectorAll('[data-ev-del]').forEach(b=>b.onclick=()=>{STATE.schedule=STATE.schedule.filter(x=>x.id!==b.dataset.evDel);save('schedule');render()});document.querySelectorAll('[data-tpl-del]').forEach(b=>b.onclick=()=>{STATE.weeklyTemplate=STATE.weeklyTemplate.filter(x=>x.id!==b.dataset.tplDel);save('weeklyTemplate');render()})}
function renderCalendar(){const start=new Date();start.setDate(1);const end=new Date(start.getFullYear(),start.getMonth()+1,0),lead=(start.getDay()+6)%7;let cells='';for(let i=0;i<lead;i++)cells+='<div class="cal-day muted"></div>';for(let i=1;i<=end.getDate();i++){const d=new Date(start.getFullYear(),start.getMonth(),i),iso=d.toISOString().slice(0,10),ev=eventsForDate(iso);cells+=`<div class="cal-day ${iso===today()?'today':''}"><b>${i}</b>${ev.slice(0,3).map(e=>`<small style="--sc:${subj(e.subject).color}">${esc(e.title)}</small>`).join('')}</div>`}return`<div class="calendar-head">${['L','M','M','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar">${cells}</div>`}
/* ---------- Bac ---------- */
const BAC=[['hg','Histoire-Géographie',6],['lva','Anglais',6],['lvb','Espagnol',6],['eps','EPS',6],['emc','EMC',2],['hggsp','HGGSP',16],['ses','SES',16],['philo','Philosophie',8],['grandoral','Grand oral',8]];
function bacProj(){const s=STATE.bacSimulation||{target:14};let p=0,c=0;for(const [id,,co] of BAC){const n=Number(s[id]);if(Number.isFinite(n)){p+=n*co;c+=co}}const missing=Math.max(0,100-c),target=Number(s.target||14);return{p,c,missing,target,projection:(p+missing*target)/100}}
function renderBac(){const p=bacProj();setMain(`<div class="page-title"><div><small>OBJECTIF</small><h2>Bac 2027</h2><p>Projection personnelle des épreuves renseignées.</p></div></div><section class="hero compact"><div><small>PROJECTION</small><h1>${p.projection.toFixed(2)} /20</h1><p>${p.c} coefficients renseignés · ${p.missing} encore à estimer.</p></div></section><section class="composer panel"><div class="section-head"><div><small>SIMULATEUR</small><h2>Mes hypothèses</h2></div></div><label class="field" style="max-width:260px"><span>Objectif utilisé pour les cases vides</span><input id="bacTarget" type="number" min="0" max="20" step="0.1" value="${p.target}"></label><div class="bac-list">${BAC.map(([id,label,co])=>`<label class="bac-row"><div><b>${label}</b><small>Coefficient ${co}</small></div><input class="bac-input" data-bac="${id}" type="number" min="0" max="20" step="0.1" value="${STATE.bacSimulation?.[id]??''}"></label>`).join('')}</div><div class="notice">HGGSP et SES sont les deux spécialités suivies dans l’application. Les règles officielles peuvent évoluer : cette page sert de simulation.</div></section><section class="section panel"><div class="section-head"><div><small>ÉCHÉANCES</small><h2>À préparer</h2></div></div><div class="list"><div class="rowitem"><div class="grow"><b>Philosophie</b><small>Épreuve terminale · juin 2027</small></div></div><div class="rowitem"><div class="grow"><b>HGGSP</b><small>Spécialité · juin 2027</small></div></div><div class="rowitem"><div class="grow"><b>SES</b><small>Spécialité · juin 2027</small></div></div><div class="rowitem"><div class="grow"><b>Grand oral</b><small>Préparation toute l’année</small></div></div></div></section>`);$('bacTarget').onchange=e=>{STATE.bacSimulation.target=Math.max(0,Math.min(20,Number(e.target.value)||14));save('bacSimulation');render()};document.querySelectorAll('[data-bac]').forEach(i=>i.onchange=e=>{const v=e.target.value.trim();if(v==='')delete STATE.bacSimulation[e.target.dataset.bac];else STATE.bacSimulation[e.target.dataset.bac]=Math.max(0,Math.min(20,Number(v)));save('bacSimulation');render()})}
/* ---------- Coaching / Excellence / Energy ---------- */
function renderCoaching(){const due=revisionDue().length,done=STATE.homework.filter(x=>x.done).length;setMain(`<div class="page-title"><div><small>ACCOMPAGNEMENT</small><h2>Coaching</h2><p>Une routine simple pour garder le rythme.</p></div></div><div class="two-col"><section class="panel coaching-card"><small>À revoir</small><b>${due}</b><p>question(s) actuellement dues</p><button class="btn primary" id="coachRev">Lancer une séance</button></section><section class="panel coaching-card"><small>Devoirs terminés</small><b>${done}</b><p>Tu gardes toujours la main sur l’état des devoirs.</p></section></div><section class="section panel"><div class="section-head"><div><small>ROUTINE</small><h2>45 minutes</h2></div></div><div class="routine"><div><span>10 min</span><b>Rappels</b><small>2 à 5 notions du dernier cours</small></div><div><span>20 min</span><b>Fiches</b><small>Retourner les cartes difficiles</small></div><div><span>15 min</span><b>QCM</b><small>Corriger les erreurs et revoir les notions faibles</small></div></div></section>`);$('coachRev').onclick=()=>startRevision(revisionDue())}
function renderExcellence(){setMain(`<div class="page-title"><div><small>ENTRAÎNEMENT</small><h2>Excellence</h2><p>Grand oral, entraînement et journal d’erreurs.</p></div></div><section class="panel"><div class="section-head"><div><small>GRAND ORAL</small><h2>Entraîne-toi avec l’IA</h2></div><button class="btn primary" id="oralAI">Générer</button></div><div class="notice">L’IA prépare des problématiques autour de HGGSP et SES avec plan court et piège à éviter.</div><div id="oralOut"></div></section><section class="section panel"><div class="section-head"><div><small>ERREURS</small><h2>Journal d’erreurs</h2></div><b>${STATE.errors.length}</b></div><div class="list">${STATE.errors.slice().reverse().slice(0,20).map(e=>`<div class="rowitem"><div class="grow"><b>${esc(e.question||'Question')}</b><small>${esc(e.subject||'Révision')}</small></div></div>`).join('')||'<div class="empty">Les erreurs de QCM pourront apparaître ici.</div>'}</div></section>`);$('oralAI').onclick=async()=>{const o=$('oralOut');o.innerHTML='<div class="notice"><span class="loading"><i class="spin"></i> Génération…</span></div>';try{o.innerHTML='<div class="ai-output"><div class="richtext">'+esc(await aiCall('Pour une élève de Terminale avec HGGSP et SES, propose 5 entraînements de Grand oral. Pour chacun : problématique, plan en 3 idées, exemple à mobiliser et piège à éviter.'))+'</div></div>'}catch(e){o.innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}}}
function renderEnergy(){const rows=STATE.energy||[];setMain(`<div class="page-title"><div><small>RYTHME</small><h2>Énergie</h2><p>Un suivi léger du temps de travail.</p></div></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Énergie /5</span><input id="energyScore" type="number" min="1" max="5" value="3"></label><label class="field"><span>Minutes travaillées</span><input id="energyMin" type="number" min="0" step="5" value="30"></label></div><div class="actions"><button class="btn primary" id="saveEnergy">Enregistrer</button></div></section><section class="section panel"><div class="list">${rows.slice().reverse().slice(0,14).map(x=>`<div class="rowitem"><div class="grow"><b>${fmt(x.date)}</b><small>${x.minutes||0} min · énergie ${x.score||'—'}/5</small></div></div>`).join('')||'<div class="empty">Aucune donnée.</div>'}</div></section>`);$('saveEnergy').onclick=()=>{STATE.energy.push({id:uid(),date:today(),score:Math.max(1,Math.min(5,Number($('energyScore').value)||3)),minutes:Math.max(0,Number($('energyMin').value)||0)});save('energy');render()}}
/* ---------- Extra modules preserved ---------- */
function renderGoals(){const todos=STATE.todos||[],goals=STATE.weeklyGoals||[];setMain(`<div class="page-title"><div><small>ORGANISATION</small><h2>Objectifs</h2><p>Petites actions concrètes plutôt qu’un gros bloc impossible à finir.</p></div></div><section class="composer panel"><div class="form-grid"><label class="field full"><span>Nouvel objectif / tâche</span><input id="goalInput" placeholder="Ex. Réviser le chapitre 3 de SES"></label></div><div class="actions"><button class="btn primary" id="goalAdd">Ajouter</button></div></section><section class="section two-col"><div class="panel"><div class="section-head"><div><small>SEMAINE</small><h2>Mes objectifs</h2></div></div><div class="list">${goals.map(g=>`<div class="rowitem"><div class="grow"><b>${esc(g.text)}</b><small>${g.done?'Terminé':'En cours'}</small></div><button class="btn small" data-goal-done="${g.id}">${g.done?'À refaire':'Terminé'}</button></div>`).join('')||'<div class="empty">Aucun objectif ajouté.</div>'}</div></div><div class="panel"><div class="section-head"><div><small>TÂCHES</small><h2>À faire</h2></div></div><div class="list">${todos.map(t=>`<div class="rowitem"><button class="iconbtn small" data-todo-done="${t.id}">${t.done?'✓':'○'}</button><div class="grow"><b>${esc(t.text||t.title||'Tâche')}</b><small>${t.done?'Terminée':'À faire'}</small></div><button class="iconbtn small danger" data-todo-del="${t.id}">×</button></div>`).join('')||'<div class="empty">Aucune tâche.</div>'}</div></div></section>`);$('goalAdd').onclick=()=>{const text=$('goalInput').value.trim();if(!text)return;STATE.weeklyGoals.push({id:uid(),text,done:false,date:today()});save('weeklyGoals');render()};document.querySelectorAll('[data-goal-done]').forEach(b=>b.onclick=()=>{const g=goals.find(x=>x.id===b.dataset.goalDone);if(g){g.done=!g.done;save('weeklyGoals');render()}});document.querySelectorAll('[data-todo-done]').forEach(b=>b.onclick=()=>{const t=todos.find(x=>x.id===b.dataset.todoDone);if(t){t.done=!t.done;save('todos');render()}});document.querySelectorAll('[data-todo-del]').forEach(b=>b.onclick=()=>{STATE.todos=todos.filter(x=>x.id!==b.dataset.todoDel);save('todos');render()})}
function renderParcoursup(){const list=STATE.parcoursupList||[];setMain(`<div class="page-title"><div><small>ORIENTATION</small><h2>Parcoursup</h2><p>Garde ta liste de formations et tes notes personnelles.</p></div></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Formation</span><input id="psName" placeholder="Licence, BTS…"></label><label class="field"><span>Ville / établissement</span><input id="psPlace" placeholder="La Rochelle…"></label></div><div class="actions"><button class="btn primary" id="psAdd">Ajouter</button></div></section><section class="section panel"><div class="list">${list.map(x=>`<div class="rowitem"><div class="grow"><b>${esc(x.name)}</b><small>${esc(x.place||'')} ${x.note?'· '+esc(x.note):''}</small></div><button class="iconbtn small danger" data-ps-del="${x.id}">×</button></div>`).join('')||'<div class="empty">Aucune formation.</div>'}</div></section>`);$('psAdd').onclick=()=>{const name=$('psName').value.trim();if(!name)return;STATE.parcoursupList.push({id:uid(),name,place:$('psPlace').value.trim(),note:''});save('parcoursupList');render()};document.querySelectorAll('[data-ps-del]').forEach(b=>b.onclick=()=>{STATE.parcoursupList=list.filter(x=>x.id!==b.dataset.psDel);save('parcoursupList');render()})}
function renderDates(){const list=STATE.examDates||[];setMain(`<div class="page-title"><div><small>CALENDRIER</small><h2>Échéances</h2><p>Ajoute les contrôles et dates importantes qui ne sont pas dans l’emploi du temps.</p></div></div><section class="composer panel"><div class="form-grid"><label class="field"><span>Intitulé</span><input id="examLabel" placeholder="Contrôle de SES"></label><label class="field"><span>Date</span><input id="examDate" type="date" value="${today()}"></label></div><div class="actions"><button class="btn primary" id="examAdd">Ajouter</button></div></section><section class="section panel"><div class="list">${list.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(x=>`<div class="rowitem"><div class="grow"><b>${esc(x.label)}</b><small>${fmtLong(x.date)}</small></div><button class="iconbtn small danger" data-exam-del="${x.id}">×</button></div>`).join('')||'<div class="empty">Aucune échéance.</div>'}</div></section>`);$('examAdd').onclick=()=>{const label=$('examLabel').value.trim();if(!label)return;STATE.examDates.push({id:uid(),label,date:$('examDate').value||today()});save('examDates');render()};document.querySelectorAll('[data-exam-del]').forEach(b=>b.onclick=()=>{STATE.examDates=list.filter(x=>x.id!==b.dataset.examDel);save('examDates');render()})}
function renderErrors(){const list=STATE.errors||[];setMain(`<div class="page-title"><div><small>RÉVISER</small><h2>Erreurs</h2><p>Chaque erreur de QCM peut devenir un point à retravailler.</p></div></div><section class="panel"><div class="section-head"><div><small>JOURNAL</small><h2>${list.length} erreur(s)</h2></div><button class="btn small" id="clearErrors">Vider</button></div><div class="list">${list.slice().reverse().map(x=>`<div class="rowitem"><span class="dot" style="--sc:${subj(Object.keys(STATE.courses).find(s=>(STATE.courses[s]||[]).some(c=>c.cards?.some(q=>q.question===x.question)))||'hggsp').color}"></span><div class="grow"><b>${esc(x.question||'Question')}</b><small>${esc(x.subject||'')} · ${fmt(x.date)}</small></div></div>`).join('')||'<div class="empty">Aucune erreur enregistrée.</div>'}</div></section>`);$('clearErrors').onclick=()=>{if(confirm('Vider le journal des erreurs ?')){STATE.errors=[];save('errors');render()}}}
function renderSharedNotes(){const notes=STATE.sharedNotes||[];setMain(`<div class="page-title"><div><small>PARTAGE</small><h2>Notes partagées</h2><p>Petites notes synchronisées avec le même espace Objectif Bac.</p></div></div><section class="composer panel"><label class="field"><span>Nouvelle note</span><textarea id="sharedText" placeholder="Une idée, une consigne, un rappel…"></textarea></label><div class="actions"><button class="btn primary" id="sharedAdd">Ajouter</button></div></section><section class="section panel"><div class="list">${notes.slice().reverse().map(x=>`<div class="rowitem"><div class="grow"><b>${fmt(x.date)}</b><small>${esc(x.text)}</small></div><button class="iconbtn small danger" data-shared-del="${x.id}">×</button></div>`).join('')||'<div class="empty">Aucune note.</div>'}</div></section>`);$('sharedAdd').onclick=()=>{const text=$('sharedText').value.trim();if(!text)return;STATE.sharedNotes.push({id:uid(),date:today(),text});save('sharedNotes');render()};document.querySelectorAll('[data-shared-del]').forEach(b=>b.onclick=()=>{STATE.sharedNotes=notes.filter(x=>x.id!==b.dataset.sharedDel);save('sharedNotes');render()})}
/* ---------- AI threads in IndexedDB ---------- */
async function loadThreads(){try{const x=await idbGet('meta','aiThreads');aiThreads=Array.isArray(x?.value)?x.value:[]}catch{aiThreads=[]}if(!aiThreads.length){try{const x=JSON.parse(storageGet('objectif-bac-ai-threads-v3')||'[]');if(Array.isArray(x))aiThreads=x}catch{}}if(!aiThreads.length){const t={id:uid(),title:'Nouvelle conversation',createdAt:Date.now(),messages:[]};aiThreads=[t];aiCurrent=t.id;await saveThreads()}if(!aiCurrent||!aiThreads.some(t=>t.id===aiCurrent))aiCurrent=aiThreads[0].id}
async function saveThreads(){const value=aiThreads.slice(0,40).map(t=>({...t,messages:(t.messages||[]).slice(-100)}));try{await idbPut('meta',{key:'aiThreads',value})}catch(e){console.warn('threads',e)}try{storageSet('objectif-bac-ai-threads-v3',JSON.stringify(value))}catch{}}
function currentThread(){return aiThreads.find(t=>t.id===aiCurrent)||aiThreads[0]}
async function openAI(force=false){if(force)active='assistant';if(!aiThreads.length)await loadThreads();aiOpenUI()}
function closeAI(){aiOpenUI(false)}
function aiOpenUI(show=true){const d=$('aiDrawer'),b=$('drawerBackdrop');d.classList.toggle('show',show);b.classList.toggle('show',show);if(show)renderAIDrawer();else aiRendered=false}
function renderAIDrawer(){const d=$('aiDrawer');if(!d)return;const t=currentThread();if(!aiRendered){d.innerHTML=`<div class="ai-shell"><header class="ai-head"><div><small>OBJECTIF BAC</small><h2>Assistant IA</h2></div><button class="iconbtn" id="aiClose">×</button></header><div class="ai-body"><aside class="threads"><button class="new-thread" id="newThread">＋ Nouvelle conversation</button><div id="threadList"></div></aside><section class="chat"><div class="chat-top"><div><b id="chatTitle"></b><small id="modelCount">Puter.js</small></div><div class="chat-tools"><select id="aiModel"></select><button class="btn small" id="aiRename">Renommer</button><button class="iconbtn small danger" id="aiDelete">×</button></div></div><div class="ai-messages" id="aiMessages"></div><div class="ai-compose"><div class="ai-suggestions"><button data-aip="Explique-moi cette notion simplement.">Expliquer</button><button data-aip="Fais-moi réviser avec 5 questions.">Me faire réviser</button><button data-aip="Aide-moi à corriger mes erreurs.">Corriger</button></div><div id="aiAttachPreview"></div><div class="compose-row"><label class="attach-btn" title="Ajouter des photos">＋<input id="aiFiles" type="file" accept="image/*" multiple hidden></label><textarea id="aiInput" rows="1" placeholder="Écris ton message…"></textarea><button class="send-btn" id="aiSend">↑</button></div></div></section></div></div>`;bindAIEvents();aiRendered=true}updateAIUI(t)}
function bindAIEvents(){ $('aiClose').onclick=closeAI;$('drawerBackdrop').onclick=closeAI;$('newThread').onclick=async()=>{const t={id:uid(),title:'Nouvelle conversation',createdAt:Date.now(),messages:[]};aiThreads.unshift(t);aiCurrent=t.id;aiPending=[];await saveThreads();updateAIUI(t)};$('aiRename').onclick=async()=>{const t=currentThread(),n=prompt('Nom de la conversation',t.title);if(n?.trim()){t.title=n.trim();await saveThreads();updateAIUI(t)}};$('aiDelete').onclick=async()=>{if(aiThreads.length===1)return;aiThreads=aiThreads.filter(x=>x.id!==aiCurrent);aiCurrent=aiThreads[0].id;await saveThreads();updateAIUI(currentThread())};$('aiModel').onchange=e=>{AI_SELECTED=e.target.value;storageSet('objectif-bac-ai-model',AI_SELECTED)};$('aiFiles').onchange=async e=>{try{aiPending.push(...await filesToImages([...e.target.files]));updateAIAttach()}catch(err){alert('Impossible de charger la photo : '+(err.message||err))}};document.querySelectorAll('[data-aip]').forEach(b=>b.onclick=()=>{$('aiInput').value=b.dataset.aip;$('aiInput').focus()});$('aiSend').onclick=sendAIMessage;$('aiInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAIMessage()}}}
async function updateAIUI(t){if(!t)return;const list=$('threadList');if(list)list.innerHTML=aiThreads.map(x=>`<button class="thread ${x.id===aiCurrent?'active':''}" data-thread="${x.id}"><b>${esc(x.title)}</b><small>${esc(x.messages?.at(-1)?.text||'Nouvelle conversation')}</small></button>`).join('');list?.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{aiCurrent=b.dataset.thread;aiPending=[];updateAIUI(currentThread())});$('chatTitle').textContent=t.title;const sel=$('aiModel');if(sel){sel.innerHTML=(AI_MODELS.length?AI_MODELS: [{id:AI_SELECTED||'gpt-5.6-luna',name:AI_SELECTED||'Modèle'}]).map(m=>`<option value="${esc(m.id)}" ${m.id===AI_SELECTED?'selected':''}>${esc(modelLabel(m))}</option>`).join('')}const box=$('aiMessages');if(box){box.innerHTML=(t.messages||[]).map(renderMsg).join('')||'<div class="empty"><b>Nouvelle conversation</b><small>Pose une question ou ajoute plusieurs photos.</small></div>';box.scrollTop=box.scrollHeight}updateAIAttach()}
function renderMsg(m){return `<div class="msg ${m.role==='user'?'user':'ai'}">${m.imageIds?.length?`<div class="msg-images">${m.imageIds.map((x,i)=>`<button class="msg-img" data-msgimg="${esc(x.id)}" data-mi="${i}"><img data-lazy-img="${esc(x.id)}"></button>`).join('')}</div>`:''}${m.text?`<div>${esc(m.text)}</div>`:''}</div>`}
function updateAIAttach(){const p=$('aiAttachPreview');if(p)p.innerHTML=aiPending.length?`<div class="attach-list">${aiPending.map((x,i)=>`<button class="attach-thumb" data-pai="${i}"><img src="${x.data}"><span>×</span></button>`).join('')}</div>`:'';p?.querySelectorAll('[data-pai]').forEach(b=>b.onclick=()=>{aiPending.splice(Number(b.dataset.pai),1);updateAIAttach()})}
async function sendAIMessage(){if(busy.has('chat'))return;const input=$('aiInput');if(!input)return;const text=input.value.trim();if(!text&&!aiPending.length)return;busy.add('chat');const t=currentThread(),imgs=aiPending.slice();t.messages.push({role:'user',text,imageIds:imgs.map(x=>({id:x.id,name:x.name}))});if(t.title==='Nouvelle conversation'&&text)t.title=text.slice(0,40);aiPending=[];input.value='';updateAIUI(t);const thinking={role:'assistant',text:'…'};t.messages.push(thinking);updateAIUI(t);try{const history=t.messages.slice(0,-1).slice(-14).map(m=>`${m.role==='user'?'Utilisateur':'Assistant'}: ${m.text||'[photos]'}`).join('\n');thinking.text=await aiCall(`Tu es l’Assistant IA d’Objectif Bac, coach scolaire de Terminale. Réponds en français, de façon claire et utile. Conserve le contexte de cette conversation.\n\n${history}\n\nDernière demande :\n${text}`,{images:imgs,max_tokens:9000});await saveThreads()}catch(e){thinking.text='Erreur IA : '+String(e.message||e)}finally{await saveThreads();busy.delete('chat');updateAIUI(t)}}
/* ---------- image binding ---------- */
async function loadLazyImages(){for(const el of [...document.querySelectorAll('[data-lazy-img]')]){const d=await mediaGet(el.dataset.lazyImg).catch(()=>null);if(d)el.src=d}document.querySelectorAll('[data-img-session]').forEach(b=>b.onclick=()=>{const c=courseById(b.dataset.imgSession);if(c)openGallery(c.imageIds,b.dataset.imgIndex)});document.querySelectorAll('[data-hwimg]').forEach(b=>b.onclick=()=>{const h=STATE.homework.find(x=>x.id===b.dataset.hwimg);if(h)openGallery(h.imageIds,b.dataset.hi)});document.querySelectorAll('[data-msgimg]').forEach(b=>b.onclick=()=>{const t=currentThread(),m=t.messages.find(x=>x.imageIds?.some(z=>z.id===b.dataset.msgimg));if(m)openGallery(m.imageIds,m.imageIds.findIndex(z=>z.id===b.dataset.msgimg))})}
/* ---------- interactions ---------- */
document.addEventListener('click',e=>{const tab=e.target.closest('[data-ctab]');if(tab){courseTab[tab.dataset.cid]=tab.dataset.ctab;const el=document.querySelector(`[data-session="${tab.dataset.cid}"]`);if(el){const c=courseById(tab.dataset.cid);el.querySelector('.session-content').innerHTML=courseTabContent(c,tab.dataset.ctab);el.querySelectorAll('.tab2').forEach(x=>x.classList.toggle('active',x===tab));loadLazyImages()}}const ch=e.target.closest('[data-open-ch]');if(ch){courseOpen=courseOpen===ch.dataset.openCh?null:ch.dataset.openCh;renderCourses()}const ed=e.target.closest('[data-edit-ch]');if(ed){const c=chaptersFor(courseSubject).find(x=>x.id===ed.dataset.editCh);if(c){const n=prompt('Nom du chapitre',c.title);if(n?.trim()){c.title=n.trim();for(const x of STATE.courses[courseSubject])if(x.chapterId===c.id&&x.title===c.title){}save('chapters');renderCourses()}}}const dc=e.target.closest('[data-del-ch]');if(dc){const c=chaptersFor(courseSubject).find(x=>x.id===dc.dataset.delCh);if(c&&confirm(`Supprimer le chapitre « ${c.title} » et ses séances ?`)){for(const x of STATE.courses[courseSubject].filter(v=>v.chapterId===c.id)){for(const im of x.imageIds||[])mediaDel(typeof im==='string'?im:im.id)}STATE.courses[courseSubject]=STATE.courses[courseSubject].filter(v=>v.chapterId!==c.id);STATE.chapters[courseSubject]=STATE.chapters[courseSubject].filter(v=>v.id!==c.id);save('chapters');save('courses');courseOpen=null;renderCourses()}}const flip=e.target.closest('[data-flip]');if(flip){flip.classList.toggle('revealed')}const ans=e.target.closest('[data-answer]');if(ans){const box=ans.closest('[data-qcm]'),[cid,i]=box.dataset.qcm.split(':'),c=courseById(cid),idx=Number(i),good=Number(ans.dataset.answer)===Number(c.cards[idx].answer);box.querySelectorAll('.answer').forEach(x=>x.disabled=true);ans.classList.add(good?'good':'bad');box.querySelector('[data-feedback]').innerHTML=`<div class="notice ${good?'ok':'error'}">${good?'Bonne réponse.':'À revoir.'} ${esc(c.cards[idx].explanation||'')}</div>`;if(!good){STATE.errors.push({id:uid(),question:c.cards[idx].question,subject:subj(courseSubjectOf(c)).name,date:today()});save('errors')}updateReview(c,idx,good?2:0)}const retry=e.target.closest('[data-retry]');if(retry){continueCoursePipeline(retry.dataset.retry)}const regen=e.target.closest('[data-regenc]');if(regen){continueCoursePipeline(regen.dataset.regenc)}const del=e.target.closest('[data-delc]');if(del){const c=courseById(del.dataset.delc);if(c){for(const x of c.imageIds||[])mediaDel(typeof x==='string'?x:x.id);for(const s of SUBJECTS)STATE.courses[s]=(STATE.courses[s]||[]).filter(x=>x.id!==c.id);save('courses');renderCourses()}}});
/* ---------- backup ---------- */
function backupModal(){const blob=new Blob([JSON.stringify(STATE,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`objectif-bac-sauvegarde-${today()}.json`;a.click();URL.revokeObjectURL(u)}
/* ---------- init ---------- */
(async()=>{await loadState();await remoteLoad();normalize();streak();await loadModels();$('fabAI').onclick=()=>openAI(true);render();loadLazyImages()})();
setInterval(()=>{if(active==='home')renderHome()},60000);
